import sys

def find_path(m, n, volcanoes):
    if len(m) != len(n[0]) or len(m[0]) != len(n) or len(m) != len(n) or len(n) != len(m[0]) or not volcanoes:
        return -1

    path = []
    stack = [(1, 1)]

    while stack:
        i, j = stack.pop()
        path.append((i, j))
        if i == len(m) - 1 and j == len(m[0]) - 1:
            break
        for dx, dy in ((1, 0), (0, 1)):
            x, y = i + dx, j + dy
            if 1 <= x <= len(m) and 1 <= y <= len(m[0]) and (x, y) not in volcanoes:
                stack.append((x, y))

    if (len(path) - 1 == path.count(path[-1])):
        return len(m) * len(m[0]) - 1 if (path.count(path[-1])) == len(path) else -1
    else:
        return len(m) * len(m[0]) - 1

