    core = [i for i in range(n) if not any(i in path for path in paths)]
    paths = [[] for _ in range(n)]

    for i in range(m):
        u, v = edges[i]
        if u not in core and v not in core:
            paths[u].append(v)
            paths[v].append(u)

    dp = [0]*n
    dp[core[0]] = 1

    for k in range(1, n):
        for i in range(k):
            dp[k] = (dp[k] + balance(paths, i, k)) % p

    return np.array(dp).sum() % p

def balance(paths, core, k):
    min_len = min(max(len(paths[u]) - core for u in paths), n - core)
    length = 0
    while min_len:
        for u in paths[:k]:
            if length % min_len == 0 and gcd(length, min_len) > 1:
                return 0

        for u in paths[:k]:
            length += 1
            if u in paths:
                length -= 1
        min_len -= 1
    return length

