import math

def dfs(x, y, n, visited, volcanoes, memo):
    if x >= n or y >= n or (x, y) in volcanoes or (x, y) in visited or memo[x][y][0] != -1:
        return memo[x][y][0]
    result_x = memo[x][y][1] = x + 1
    result_y = memo[x][y][2] = y + 1
    visited.add((x, y))
    for dx, dy in [(-1, 0), (0, -1)]:
        if (max(1, x + dx), max(1, y + dy)) not in visited and (max(1, x + dx), max(1, y + dy)) not in volcanoes and x + dx >= 1 and y + dy >= 1:
            result_x, result_y = min(result_x, dfs(x + dx, y, n, visited, volcanoes, memo)), min(result_y, dfs(x, y + dy, n, visited, volcanoes, memo))
    memo[x][y][0], memo[x][y][1], memo[x][y][2] = result_x, min(result_x, y + 1), min(result_y, x + 1)
    return memo[x][y][0]

def calculate_time(n, volcanoes):
    if (sum(1 for _ in volcanoes.values()) + 1) % 2 == 0:
        return -1
    min_cost, min_cost_path = math.inf, []
    for x in range(1, n + 1):
        for y in range(1, n + 1):
            visited = {cell for cell, (v, q, r) in volcanoes.items() if not v}
            cost = dfs(x + 1, y + 1, n + 1, visited, volcanoes, {(x, y): 1})
            if cost < min_cost:
                min_cost = cost
                min_cost_path = [(x, y)]
            elif cost == min_cost:
                min_cost_path.append((x, y))
    if min_cost == -1:
        return -1
    return min_cost + (n * (n + 1) // 2 - (sum((x[0] + x[1]) % 2 == 0 for x in min_cost_path) + (0 in min_cost_path) + len(min_cost_path) > 1))

# Example usage
