    return s

def build_solution(a: str) -> str:
    """Generate the lexicographically smallest string after applying all possible operations."""
    non_decreasing = Counter()
    decreasing = Counter()
    all_counter = Counter()

    n = len(a)
    for i in range(n):
        if a[i] == '0':
            non_decreasing[a[i]] += 1
            to_flip = counter_prefix_non_decreasing(non_decreasing)
            char_to_add = '0' if (non_decreasing['1'] + 128 - non_decreasing['0']  > 64) else '1'
            all_counter[i+to_flip+1] += 1
            all_counter[i+to_flip+2*(i//64)] += non_decreasing[char_to_add]
            if non_decreasing[char_to_add] > non_decreasing['1'] - 64:
                continue
        else:
            non_decreasing['1'] += 1
            all_counter[i] += 1
        counter_prefix_non_decreasing = non_decreasing.keys()

