            has_maneuver[node] = True
            travels_to(source, edges, traveled, node, path_count + 1, has_maneuver, cycle_count)
            has_maneuver[node] = False

def is_valid_path(edges, traveled, destination, has_maneuver):
    return traveled[destination] >= 1 and not has_maneuver[destination] and is_cycled(edges, traveled)

