    cycle_exists = False
    for i in range(n):
        for j in range(n):
            if j == i or edges[i][j] == 0:
                continue
            if j not in traveled:
                continue
            for k in range(n):
                if k not in traveled:
                    cycle_exists = is_valid_path(edges, traveled, j, 0, 1, [], cycle_exists)
    return cycle_exists

