from collections import defaultdict

def count_cycles():
    n, m = map(int, input().split())
    road_map = defaultdict(list)
    for _ in range(m):
        ai, bi = map(int, input().split())
        road_map[ai].append(bi)
        road_map[bi].append(ai)
    visited = [False] * (n + 1)
    cycle_count = 0

    def dfs(current_node, depth):
        nonlocal cycle_count
        visited[current_node] = True
        if depth == 5 and not visited[next_node] and len(road_map[next_node]) == 4:
            cycle_count += 1
        for next_node in road_map[current_node]:
            if not visited[next_node] and len(road_map[next_node]) == 4:
                dfs(next_node, depth + 1)
        visited[current_node] = False

    for node in range(1, n + 1):
        if len(road_map[node]) == 4:
            dfs(node, 1)

    return cycle_count

