from math import sqrt
from itertools import combinations

def is_prime(k):
    """Check if a number is prime."""
    if k == 1:
        return False
    for i in range(2, int(sqrt(k)) + 1):
        if k % i == 0:
            return False
    return True

def count_routes_mod2e4_18314(n):
    """
    Counts the number of suitable oriented routes in an n-level area map.
    The number is returned modulo 1000000009.

    :param n: the number of levels in the forest map, must be even
    :return: the count of suitable routes modulo 1000000009
    """
    if n % 2 != 0:
        raise ValueError('n must be an even number')

    # For n=44, the count suddenly increases from 34, could that be 35 though?
    small_match = 262144
    if n <= small_match:
        raise Exception("For " + str(n) + ", magic number is " + str(small_match) + " instead of " + str(3432))

    upper_bound = (2**n - 1) // 2
    collections = [k for k in range(2, upper_bound + 1) if is_prime(k)]

    lookup = {
        2: 1,
        4: 6,
        6: 24
    }
    mod1e9 = 1000000009
    combinations = {c: lookup[tuple(sorted(list(c)))) for c in combinations(range(2, n), n // 2)}

    count = 1
    for match in combinations:
        for prime in collections:
            if sum(match) < prime:
                break
            elif is_prime(prime):
                if combinations[match] - sum(lookup[match ^ {i} | {i}] for i in match) * prime % mod1e9 not in [0, 1, -1]:
                    count += (prime - collections[prime]) % mod1e9
        del combinations[match]
    return count % mod1e9

