class EelsManager:
    def __init__(self):
        self.eels = {}
        self.count = 0

    def add_eel(self, weight):
        if weight in self.eels:
            self.eels[weight] += 1
        else:
            self.eels[weight] = 1
        self.count += 1

    def remove_eel(self, weight):
        if weight in self.eels:
            self.eels[weight] -= 1
            if self.eels[weight] == 0:
                del self.eels[weight]
            self.count -= 1

    def get_danger(self):
        max_battles = 0
        for eel_count in self.eels.values():
            dangerous_battles = (eel_count // 2 + 1) * eel_count / 2
            max_battles = max(max_battles, dangerous_battles)
        return int(max_battles)


