    scores = {"tred": 0, "district": 0, "miniclimb": 0, "zero": 0, "tandem": 0, "dynamic": 0, "data": 0, "compete": 0, "initial": 0, "highway": 0}

    while True:
        queries = input().split()
        if queries == ["stop"]:
            print("done")
            break

        players = list(range(len(queries)))
        responses, _, response_count = zip(*((range(len(players)), players, (scores[players[i]] := int(qs)) for i, qs in enumerate(queries))))

        median = statistics.median(scores.values())

        # Distribute players along the path based on median score
        for p in players:
            if scores[p] < median:
                responses[p] = 0
            elif scores[p] > median:
                responses[(t*p)%10] = responses[(t*p-1)%10] + 1

        # Flush stdout after each query
        for response in responses:
            print(f"next {response}")
            for response_idx in range(1, response + 1):
                print(flush=True)

