from collections import deque

def calculate_danger(eels):
    operations = [0] * (len(eels) + 1)
    for i in range(len(eels)):
        operations[i] += eels[i] // 2
        operations[i + 1] += eels[i] % 2

    monsters = deque(sorted([(e / 2, e % 2) for e in eels]))
    d = 0
    while monsters:
        while monsters and monsters[0][0] <= d:
            monsters.popleft()

        if monsters:
            horrendous = monsters[0][1]
            if horrendous != 0:
                operations[1] += horrendous
                monsters.popleft()

        d += 1

    return operations.count(d)

