from itertools import accumulate

def flip(s, index):
    return s[:index] + ''.join('0' if c == '1' else '1' for c in s[index::-1])

def reverse(s, index):
    return s[::-1][index:][::-1]

def get_min_string(s):
    # Helper function to get the prefix information
    def get_prefix_info(index):
        if index == 0:
            return 0, 0
        half = len(s) // 2
        offset, size = get_prefix_info(index - half)
        l0, l1 = get_prefix_info(index - 1) if index % 2 == 0 else (half, size - half)
        l0 += l1
        if index < len(s) - 1 and s[index] == s[index + 1]:
            l0 += 1
        return (index, offset + size) if index - 1 >= offset else (index - size, offset - size)

    # Calculate how many 0's and 1's there are in each position from 0 to last
    positions = list(accumulate(len(s) - (mid % 2), reduce(lambda x, y: (x + (y + y > 0) - y, 0)) for mid in range(len(s))))
    res = ''.join(['0' for _ in range(positions[-1])])

    def dfs(index):
        if index == len(s):
            return
        suffix = s[index:] if index < len(s) else ''
        candidates = []
        offset = [0, 0]
        for pos, c in [(-1, 1), (0, 1), (1, 1), (0, -1)]:
            for sign in [1, -1]:
                op = (len(res[index::2]), -len(suffix))(offset)
                for r in range(op + sign, op + sign + sign + 1):
                    suffix_fp = s[index + r]
                    c0, c1 = positions[index + r - 1]
                    if suffix_fp == suffix[index + r] and r > op:
                        res = flip(res, index + pos)
                        break
                    if suffix_fp == flip(suffix, index + pos):
                        res = reverse(res, index + pos)
                    curr = (0, 0) if sign == 1 else (c0, c1 - c0)
                    op += offset[sign]
                    if r >= op:
                        candidates.append(curr)
        candidates.sort()
        res = ''.join(chrs for c in candidates for chrs in (accumulate(c, lambda s, c: c + s,) for c in c)[candidates[0]] + (0,))
        return res

    return dfs(len(s) - 1)

