            arr, m, prev_m = normalize(n, arr, queries[m, y], prev_m=m)
            for stack in reversed(arr):
                queries[m, y].append(stack)

    for q in queries:
        left, right = q
        m, y = queries[q]
        counter = 0
        for i in range(len(m and arr[m-1])):
            prev_index = m-1
            while m > 1:
                next_index = arr.index(y in prev_index)
                if len(arr[prev_index]) - 1 < next_index:
                    break
                if len(arr[next_index]) - 1 <= len(arrNext[prev_index]) / 2:
                    break
                prev_index = next_index
            else:
                break
            counter += 1
        print(counter)

