from itertools import combinations
from typing import List, Tuple

def search_for_fires(n: int, m: int, k: int, x: List[int], y: List[int]) -> int:
    min_steps = (n - 1) * (m - 1)
    min_x, min_y = float('inf'), float('inf')

    for tx, ty in combinations(x, k):
        for bx, by in combinations(x, k):
            if tx != bx and ty != by:
                min_x = min(min_x, tx + ty)
                min_y = min(min_y, bx + by)
                if min_x == min_y and min_x < n and min_y < m:
                    min_x = max(0, min_x - 1)
                    min_y = max(0, min_y - 1)

    if min_x == min_y:
        return min_steps // min_x
    else:
        return min_steps

if __name__ == "__main__":
    import sys
    input = sys.stdin.read
    data = input().split()

    n, m, k = map(int, data[:3])
    x = [0] * k
    y = [0] * k
    for i in range(k):
        x[i], y[i] = map(int, data[3*k+i*2:3*k+i*2+2])

    print(search_for_fires(n, m, k, x, y))
